import networkx as nx
import numpy as np
from collections import deque

def select_next_node(graph, unvisited_nodes):
    unvisited_set = set(unvisited_nodes)
    core = {n: graph.nodes[n]['core_number'] for n in unvisited_nodes}
    betw = {n: graph.nodes[n]['betweenness'] for n in unvisited_nodes}

    # Parameters
    MAX_DEPTH = 3  # limit BFS depth to control complexity

    # Precompute weighted node scores (core * betw) for unvisited nodes
    weighted_scores = {n: core[n] * betw[n] for n in unvisited_nodes}
    if not weighted_scores:
        return unvisited_nodes[0]  # fallback

    # For each candidate node, compute Weighted Reachability Score (WRS):
    # Sum over reachable nodes (up to MAX_DEPTH) of weighted_scores[node] / distance
    # The candidate node itself is excluded from summation.
    def weighted_reachability(candidate):
        visited = {candidate}
        queue = deque([(candidate, 0)])
        score = 0.0

        while queue:
            curr, dist = queue.popleft()
            if dist == MAX_DEPTH:
                continue
            dist_next = dist + 1
            for nbr in graph.neighbors(curr):
                if nbr in unvisited_set and nbr not in visited:
                    visited.add(nbr)
                    # Inverse distance weighted by node's core*betw score
                    w_score = weighted_scores.get(nbr,0)
                    if dist_next > 0:
                        score += w_score / dist_next
                    queue.append((nbr, dist_next))
        return score

    best_node = None
    best_score = -1

    for node in unvisited_nodes:
        wrs = weighted_reachability(node)
        if wrs > best_score:
            best_score = wrs
            best_node = node

    return best_node
